struct Cache { state: State }           // one field = the whole representation

impl Cache {
    fn swap_state(&mut self, other: &mut Cache) {
        std::mem::swap(&mut self.state, &mut other.state);  // O(1), cannot panic
    }

    fn commit(&mut self, fresh: State) -> State {
        std::mem::replace(&mut self.state, fresh)           // returns the old state
    }
}
